INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('SP001', 0, '{"id":"SP001","name":"Núi Ngũ Chỉ Sơn","area":"Núi Ngũ Chỉ Sơn","lat":22.415,"lng":103.745,"type":"nature","moods":["adventure","energy"],"groups":["solo","friends"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":720,"cost":1500000,"desc":"Cụm 5 ngọn núi đá chọc thẳng lên trời (cao 2.858m) tựa bàn tay khổng lồ giữa biển mây, nổi tiếng với vách đá dựng đứng, rừng trúc lùn và rừng rêu cổ thụ.","badges":["1,2–3,8 triệu","Trekking mạo hiểm","Ngoài trời"],"tip":"Đi tháng 10–4 ngày nắng ráo (tháng 10–12 săn mây, tháng 2–4 hoa đỗ quyên). Xuất phát 7:00–8:00 sáng; săn mây từ 4:30–5:00 sáng. Tránh tuyệt đối ngày mưa."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('SP002', 1, '{"id":"SP002","name":"Vườn Quốc gia Hoàng Liên","area":"VQG Hoàng Liên","lat":22.3167,"lng":103.7667,"type":"nature","moods":["calm","adventure","energy"],"groups":["solo","couple","friends","family"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":240,"cost":70000,"desc":"Vườn Di sản ASEAN và trung tâm đa dạng sinh học bậc nhất Việt Nam, sở hữu đỉnh Fansipan (3.143m), quần thể cây di sản và hơn 40 loài hoa đỗ quyên.","badges":["70.000đ","Tắm rừng & Trekking","Ngoài trời"],"tip":"Đẹp nhất 8:30–16:30. Tháng 9–11 lúa chín trời trong; tháng 12–2 săn băng tuyết; tháng 3–5 mùa đỗ quyên. Tránh mùa mưa lũ tháng 6–8."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('SP003', 2, '{"id":"SP003","name":"Hồ Séo Mý Tỷ","area":"Hồ Séo Mý Tỷ","lat":22.2536,"lng":103.8967,"type":"nature","moods":["calm","adventure"],"groups":["solo","couple","friends"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":240,"cost":0,"desc":"Hồ nước ngọt nhân tạo cao nhất Việt Nam (1.600m) nằm sâu trong lõi VQG Hoàng Liên, mặt hồ trong xanh uốn lượn như dải lụa giữa mây mù và hai sườn núi lớn.","badges":["Miễn phí vé","Cắm trại & SUP","Ngoài trời"],"tip":"Đi ngày nắng ráo (tháng 9–4). Xuất phát 7:00–8:00 đón sương tan hoặc 14:00–15:30 nếu cắm trại. Không đi đèo sau 17:30 vì đường đá hộc dốc gắt không đèn."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('SP004', 3, '{"id":"SP004","name":"Bản Tả Phìn","area":"Bản Tả Phìn","lat":22.3931,"lng":103.8344,"type":"attraction","moods":["nostalgia","calm"],"groups":["solo","couple","friends","family"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":180,"cost":40000,"desc":"Bản làng cổ của người Dao Đỏ và H’Mông giữa thung lũng ruộng bậc thang, nổi tiếng với Tu Viện Tả Phìn bằng đá ong rêu phong (1942) và bài thuốc tắm lá Dao Đỏ.","badges":["Vé 40.000đ","Văn hóa & Chụp ảnh Vintage","Ngoài trời"],"tip":"Khung giờ 8:00–11:00 hoặc 14:00–17:00 nắng chiếu xiên qua tường đá Tu Viện đẹp nhất để chụp ảnh vintage/Y2K. Nên ngâm lá thuốc Dao Đỏ (100k–150k) để giãn cơ."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('SP005', 4, '{"id":"SP005","name":"Thác Tình Yêu (Thác Tình)","area":"Thác Tình Yêu","lat":22.3486,"lng":103.7764,"type":"nature","moods":["calm","nostalgia","energy"],"groups":["couple","friends","family","solo"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":120,"cost":75000,"desc":"Ngọn thác cao gần 100m tuôn trào từ đỉnh Fansipan cùng cung đường đi bộ 1,5 km xuyên rừng trúc xanh rì dọc bờ Suối Vàng óng ả như mật ong.","badges":["Vé 75.000đ","Hiking nhẹ & Suối Vàng","Ngoài trời"],"tip":"Đi từ 8:30–15:00 ngày nắng để thấy cầu vồng dưới chân thác và Suối Vàng lên màu đẹp nhất. Vào trước 15:30 vì rừng già nhanh tối, đóng cửa lúc 17:00."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN001', 5, '{"id":"NN001","name":"Sapa Relax Hotel & Spa","area":"VQG Hoàng Liên","lat":22.3338,"lng":103.8431,"type":"lodging","moods":["calm","energy"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":950000,"desc":"Khách sạn 3 sao sạch sẽ ngay trung tâm thị xã với tầm nhìn bao quát, có spa thư giãn và buffet sáng giàu đạm (nhiều trứng, thịt) hỗ trợ tốt giai đoạn bulking.","badges":["700k–1,2tr/đêm","Khách sạn 3 sao","Trong nhà"],"tip":"Cách ga cáp treo Fansipan ~2 km và Thác Tình Yêu ~12 km. Tận dụng buffet sáng nhiều thịt và trứng để nạp đủ protein trước khi đi tham quan."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN002', 6, '{"id":"NN002","name":"Silk Path Grand Sapa Resort & Spa","area":"VQG Hoàng Liên","lat":22.3389,"lng":103.8415,"type":"lodging","moods":["calm","nostalgia","energy"],"groups":["couple","family","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":2750000,"desc":"Resort 5 sao kiến trúc lâu đài châu Âu giữa vườn hoa hồng cổ, trang bị hồ bơi nước nóng trong nhà, 3 nhà hàng và phòng Gym đầy đủ tạ hiện đại.","badges":["2,0–3,5tr/đêm","Resort 5 sao & Gym","Trong nhà"],"tip":"Cách ga tàu hỏa Mường Hoa 1,5 km, cửa ngõ VQG Hoàng Liên 13 km. Có phòng gym đầy đủ thiết bị giúp duy trì lịch tập Push-Pull-Legs khi đi du lịch."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN003', 7, '{"id":"NN003","name":"Hotel de la Coupole – MGallery","area":"VQG Hoàng Liên","lat":22.3347,"lng":103.8406,"type":"lodging","moods":["nostalgia","calm","energy"],"groups":["couple","family","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":4750000,"desc":"Khách sạn 5 sao quốc tế siêu sang mang phong cách Haute Couture Pháp Đông Dương, sở hữu bể bơi nước nóng Le Grand Bassin, nhà hàng Chic và spa cao cấp.","badges":["3,5–6,0tr+/đêm","Siêu sang 5 sao","Trong nhà"],"tip":"Nằm trong tòa nhà Sun Plaza, kết nối trực tiếp với ga tàu hỏa leo núi Mường Hoa đi thẳng lên cáp treo Fansipan cực kỳ tiện lợi."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN004', 8, '{"id":"NN004","name":"Sapa Pine Hill Eco Lodge","area":"Núi Ngũ Chỉ Sơn","lat":22.3405,"lng":103.838,"type":"lodging","moods":["calm","adventure"],"groups":["solo","couple","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":1150000,"desc":"Khu nghỉ dưỡng bungalow gỗ len lỏi giữa đồi thông yên tĩnh ở hướng Tây Bắc thị xã, có nhà hàng và quán cà phê view núi thư thái trước ngày leo núi.","badges":["800k–1,5tr/đêm","Bungalow đồi thông","Trong nhà"],"tip":"Cách chân núi Ngũ Chỉ Sơn ~25 km, rất tiện rẽ ra Tỉnh lộ 155 để xuất phát đi trekking từ sáng sớm."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN005', 9, '{"id":"NN005","name":"Sapa Jade Hill Resort & Spa","area":"Núi Ngũ Chỉ Sơn","lat":22.3215,"lng":103.854,"type":"lodging","moods":["calm","nostalgia"],"groups":["couple","family","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":3500000,"desc":"Khu nghỉ dưỡng sinh thái nổi tiếng với các biệt thự mái cọ có lò sưởi củi mộc mạc và dịch vụ ngâm tắm lá thuốc Dao Đỏ phục hồi cơ thể chuyên sâu.","badges":["2,5–4,5tr/đêm","Biệt thự & Tắm lá thuốc","Trong nhà"],"tip":"Cách chân núi Ngũ Chỉ Sơn ~30 km. Rất lý tưởng để ngâm tắm lá thuốc Dao Đỏ giãn cơ, phục hồi sau ngày leo vách đá Ngũ Chỉ Sơn."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN006', 10, '{"id":"NN006","name":"Ville De Mont Mountain Resort","area":"Núi Ngũ Chỉ Sơn","lat":22.318,"lng":103.858,"type":"lodging","moods":["calm","nostalgia"],"groups":["couple","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":11500000,"desc":"Khu nghỉ dưỡng siêu sang biệt lập trên sườn núi với các villa xây thủ công từ đá nguyên khối và gỗ linh sam ẩn trong rừng thông sương mù.","badges":["8,0–15,0tr+/đêm","Villa đá siêu sang","Trong nhà"],"tip":"Cách Ngũ Chỉ Sơn 30–32 km. Nội thất mộc mạc kết hợp ánh sáng tự nhiên tại đây cực kỳ ăn ảnh khi chụp bằng máy ảnh compact Y2K hoặc mirrorless cổ điển."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN007', 11, '{"id":"NN007","name":"Eco Palms House - Sapa Retreat","area":"Hồ Séo Mý Tỷ","lat":22.3025,"lng":103.879,"type":"lodging","moods":["calm","nostalgia"],"groups":["couple","solo","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":1400000,"desc":"Khu nghỉ dưỡng sinh thái gồm các bungalow tre, gỗ, mái lá nhìn thẳng xuống Thung lũng Mường Hoa, có đệm sưởi ấm, massage thảo dược và ẩm thực giàu đạm.","badges":["1,1–1,7tr/đêm","Bungalow view thung lũng","Trong nhà"],"tip":"Cách Hồ Séo Mý Tỷ 12–13 km ngay trục đường chính trước khi rẽ lên đèo. Hiên gỗ rộng đón nắng sớm rất hợp chụp ảnh phong cảnh hoài cổ."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN008', 12, '{"id":"NN008","name":"Khách sạn Pao’s Sapa Leisure","area":"Hồ Séo Mý Tỷ","lat":22.3275,"lng":103.8495,"type":"lodging","moods":["energy","calm"],"groups":["couple","friends","family","solo"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":2600000,"desc":"Khách sạn 5 sao uốn lượn theo dáng ruộng bậc thang cuối đường Mường Hoa, có phòng Gym hiện đại đầy đủ máy cáp/tạ đơn, hồ bơi nước nóng và tắm lá Dao Đỏ.","badges":["2,0–3,2tr/đêm","Khách sạn 5 sao & Gym","Trong nhà"],"tip":"Cách Hồ Séo Mý Tỷ 16–17 km, đi thẳng xuống Tả Van không cần qua trung tâm đông đúc. Phòng Gym chuẩn và buffet sáng giàu đạm rất hợp người tập thể hình."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN009', 13, '{"id":"NN009","name":"Topas Ecolodge","area":"Hồ Séo Mý Tỷ","lat":22.2686,"lng":103.9372,"type":"lodging","moods":["calm","adventure"],"groups":["couple","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":9250000,"desc":"Khu nghỉ dưỡng sinh thái hạng sang hàng đầu thế giới trên hai đỉnh đồi hình nón, gồm các bungalow đá granit trắng Bắc Âu và 2 bể bơi vô cực nước nóng giữa mây.","badges":["6,5–12,0tr+/đêm","Ecolodge hạng sang","Trong nhà"],"tip":"Cách Hồ Séo Mý Tỷ 14–15 km. Có xe đưa đón miễn phí theo khung giờ từ trung tâm Sa Pa, Rice Spa cao cấp và nhà hàng 360 độ."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN010', 14, '{"id":"NN010","name":"Ta Phin Cottage","area":"Bản Tả Phìn","lat":22.391,"lng":103.836,"type":"lodging","moods":["calm","nostalgia"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":700000,"desc":"Bungalow ốp gỗ thông ấm cúng ngay trong lõi Bản Tả Phìn, bao quanh bởi vườn đào mận, phục vụ tắm lá thuốc Dao Đỏ đun củi tại chỗ và đốt lửa trại BBQ.","badges":["500k–900k/đêm","Bungalow bản địa","Trong nhà"],"tip":"Nằm ngay trong bản (0 km), cách Tu Viện Tả Phìn 1,5 km và Hang Tả Phìn 1 km. Đặt trước tắm lá thuốc đun củi và gà đồi nướng cho bữa tối."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN011', 15, '{"id":"NN011","name":"Stone Garden Resort & Spa","area":"Bản Tả Phìn","lat":22.3925,"lng":103.835,"type":"lodging","moods":["calm","nostalgia"],"groups":["couple","family","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":1400000,"desc":"Khu nghỉ dưỡng sinh thái lớn nhất trong Bản Tả Phìn nằm xen kẽ bãi đá cổ rêu phong và ruộng bậc thang, có bồn gỗ Pơ-mu tắm lá Dao Đỏ và xông hơi trị liệu.","badges":["1,0–1,8tr/đêm","Resort vườn đá cổ","Trong nhà"],"tip":"Cách Tu Viện Tả Phìn ~1 km (3 phút đi xe) và Hang Tả Phìn <800 m. Khuôn viên nhiều tiểu cảnh đá rêu phong cực hợp chụp máy ảnh kỹ thuật số cổ điển."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN012', 16, '{"id":"NN012","name":"KK Sapa Hotel","area":"Bản Tả Phìn","lat":22.3315,"lng":103.8458,"type":"lodging","moods":["energy","calm"],"groups":["couple","family","friends","solo"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":3100000,"desc":"Khách sạn 5 sao 18 tầng với tầm nhìn toàn cảnh núi rừng, trang bị phòng Gym 5 sao, bể bơi 4 mùa nước ấm, Đào Mây Spa và buffet sáng giàu protein.","badges":["2,2–4,0tr/đêm","Khách sạn 5 sao & Gym","Trong nhà"],"tip":"Cách Bản Tả Phìn ~12 km đường nhựa lớn dễ đi. Buffet sáng có nhiều ức gà, bò hầm, trứng, thịt nguội giúp kiểm soát tốt lượng đạm mỗi ngày."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN013', 17, '{"id":"NN013","name":"Viettrekking Sapa","area":"Thác Tình Yêu","lat":22.3312,"lng":103.8375,"type":"lodging","moods":["adventure","calm","energy"],"groups":["solo","couple","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":1100000,"desc":"Tổ hợp khách sạn và bungalow gỗ trên sườn đồi cao, nổi tiếng với ban công săn biển mây, quán cà phê ngắm tàu hỏa leo núi Mường Hoa và nhà hàng lẩu cá tầm.","badges":["800k–1,4tr/đêm","Săn mây & Cafe tàu hỏa","Trong nhà"],"tip":"Cách Thác Tình Yêu ~14 km. Sáng sớm ra ban công hoặc khu cà phê để săn biển mây và chụp khoảnh khắc tàu hỏa đỏ chạy ngang thung lũng."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN014', 18, '{"id":"NN014","name":"Pistachio Hotel Sapa","area":"Thác Tình Yêu","lat":22.3368,"lng":103.8388,"type":"lodging","moods":["energy","calm"],"groups":["couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":2200000,"desc":"Khách sạn 4 sao rưỡi kết hợp kiến trúc hiện đại và thổ cẩm vùng cao, nổi bật với bể bơi vô cực 4 mùa mạ vàng tầng thượng, phòng Gym và Red Dao Spa.","badges":["1,6–2,8tr/đêm","Bể bơi vô cực mạ vàng","Trong nhà"],"tip":"Nằm trên đường Thác Bạc ngay cửa ngõ phía Tây thị xã, cách cổng Suối Vàng – Thác Tình Yêu ~12 km nên di chuyển lên đèo Ô Quy Hồ rất nhanh."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('NN015', 19, '{"id":"NN015","name":"Lady Hill Sapa Resort","area":"Thác Tình Yêu","lat":22.3415,"lng":103.8365,"type":"lodging","moods":["calm","energy"],"groups":["couple","family","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":720,"cost":4150000,"desc":"Resort 5 sao thiết kế hình khuyên tai truyền thống giữa đồi thông biệt lập 22 ha, sở hữu bể bơi vô cực nước nóng ngoài trời, xông hơi Jjim Jil Bang Hàn Quốc và phòng Gym.","badges":["2,8–5,5tr/đêm","Resort 5 sao & Jjim Jil Bang","Trong nhà"],"tip":"Cách Suối Vàng – Thác Tình Yêu 11,5–12 km. Xông hơi Jjim Jil Bang tại đây cực tốt để giãn cơ và thải độc sau khi đi bộ đường rừng ở Thác Tình Yêu."}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM001', 20, '{"id":"AM001","name":"Quán Côn Đồ","area":"VQG Hoàng Liên","lat":22.3392,"lng":103.8398,"type":"food","moods":["energy","adventure"],"groups":["friends","solo","couple"],"indoor":true,"timeOfDay":["afternoon","evening"],"duration":60,"cost":160000,"desc":"Quán lẩu và đồ nướng xiên que than hồng đậm chất phố núi về đêm với bò cuốn cải mèo, lợn bản nướng, cá suối nướng tẩm ướp hạt dổi mắc khén.","badges":["Ước tính ~160.000đ","120k–200k/người","Nướng Tây Bắc","Trong nhà"],"tip":"Cách Thác Tình Yêu ~11 km, ga cáp treo Fansipan ~3 km. Điểm nạp lượng lớn thịt nạc và tinh bột nhanh chóng với chi phí tiết kiệm sau khi đi bộ rừng.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM002', 21, '{"id":"AM002","name":"Nhà hàng Ô Quy Hồ (Thạch Sơn)","area":"VQG Hoàng Liên","lat":22.3362,"lng":103.8425,"type":"food","moods":["nostalgia","calm","energy"],"groups":["couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":75,"cost":350000,"desc":"Không gian gỗ thông và đèn lồng thổ cẩm vàng ấm cổ điển, nổi tiếng với món Gà đen tiềm bí đỏ giàu đạm, lẩu cá tầm, gỏi cá hồi và xôi ngũ sắc.","badges":["Ước tính ~350.000đ","250k–450k/người","Gà đen tiềm bí đỏ","Trong nhà"],"tip":"Cách ga tàu hỏa Mường Hoa 500m, Trạm Tôn ~13 km. Góc ban công gỗ và đèn vàng ấm lên hình cực hợp với máy ảnh màu cổ điển.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM003', 22, '{"id":"AM003","name":"Nhà hàng Chic (Hotel de la Coupole)","area":"VQG Hoàng Liên","lat":22.3347,"lng":103.8406,"type":"food","moods":["nostalgia","calm"],"groups":["couple","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":90,"cost":1300000,"desc":"Nhà hàng Fine Dining Pháp Đông Dương thập niên 1920 tại tầng 10 Hotel de la Coupole, phục vụ bò Wagyu/bò Úc nướng tảng, gan ngỗng áp chảo và cá tầm sốt kem nghệ tây.","badges":["Ước tính ~1.300.000đ","800k–1,8tr+/người","Fine Dining Pháp","Trong nhà"],"tip":"Kết nối trực tiếp ga đi Fansipan (0 km). Đặt bàn cạnh ban công hoặc lò sưởi lớn để ngắm dãy Hoàng Liên Sơn và thưởng thức bò nướng giàu protein tinh khiết.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM004', 23, '{"id":"AM004","name":"Các quán ăn bản địa chợ Tả Giàng Phình (Quán Tuấn Liên)","area":"Núi Ngũ Chỉ Sơn","lat":22.408,"lng":103.758,"type":"food","moods":["energy","adventure"],"groups":["solo","friends"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":45,"cost":85000,"desc":"Quán ăn dân dã của người Mông và Dao ngay chân núi, phục vụ phở bò vùng cao thái tay dày miếng, thắng cố, thịt lợn bản rang cháy cạnh, trứng rán và cải mèo.","badges":["Ước tính ~85.000đ","50k–120k/người","Cơm bản & Tiếp sức Trekker","Trong nhà"],"tip":"Cách điểm leo núi Ngũ Chỉ Sơn chỉ 2–3 km (~10 phút). Có chỗ để xe rộng rãi, có thể nhờ gửi đồ và sạc điện thoại trước/sau khi leo núi.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM005', 24, '{"id":"AM005","name":"Trang trại & Nhà hàng Cá hồi Song Nhi (Thác Bạc)","area":"Núi Ngũ Chỉ Sơn","lat":22.3625,"lng":103.7795,"type":"food","moods":["calm","energy"],"groups":["friends","family","couple","solo"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":75,"cost":400000,"desc":"Nhà hàng bên suối lạnh tự nhiên dưới chân Thác Bạc, khách tự chọn cá hồi/cá tầm bơi tại bể chế biến đủ món: sashimi, da cá chiên, cá nướng giấy bạc và lẩu.","badges":["Ước tính ~400.000đ","300k–500k/người","Cá hồi tươi tại suối","Trong nhà"],"tip":"Cách chân núi Ngũ Chỉ Sơn ~12 km ngay gần ngã ba rẽ vào Tỉnh lộ 155. Cá hồi tươi giàu Omega-3 và đạm sạch giúp giảm viêm cơ khớp sau ngày leo vách đá.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM006', 25, '{"id":"AM006","name":"Nhà hàng Noj (Sapa Jade Hill Resort)","area":"Núi Ngũ Chỉ Sơn","lat":22.3215,"lng":103.854,"type":"food","moods":["calm","nostalgia"],"groups":["couple","family","friends"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":90,"cost":900000,"desc":"Nhà hàng kiến trúc chợ phiên vùng cao kết hợp vách kính lớn nhìn xuống thung lũng Mường Hoa, chuyên ẩm thực Fusion bản địa: lợn bản hấp lá móc mật, bò nướng ống tre.","badges":["Ước tính ~900.000đ","600k–1,2tr/người","Ẩm thực Fusion & Lò sưởi củi","Trong nhà"],"tip":"Cách Ngũ Chỉ Sơn 28–30 km, phù hợp cho bữa tối sang trọng bên lò sưởi củi ấm áp sau khi hoàn thành chuyến trekking quay về thị xã.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM007', 26, '{"id":"AM007","name":"Khu lán trại & Quán nướng ven đập Séo Mý Tỷ","area":"Hồ Séo Mý Tỷ","lat":22.2536,"lng":103.8967,"type":"food","moods":["adventure","calm","energy"],"groups":["friends","couple","solo"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":60,"cost":130000,"desc":"Các chòi gỗ mộc mạc và lán bạt dựng sát mép nước Hồ Séo Mý Tỷ, phục vụ gà bản nướng than hoa nguyên con, thịt lợn bản xiên nướng, cơm lam và mì tôm trứng bò.","badges":["Ước tính ~130.000đ","80k–180k/người","BBQ dã ngoại sát mặt hồ","Ngoài trời"],"tip":"Nằm ngay bờ đập Hồ Séo Mý Tỷ (0 km). Có thể gọi món nướng sẵn hoặc thuê bếp than, vỉ nướng tại chỗ để tự nướng BBQ bên bờ hồ.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM008', 27, '{"id":"AM008","name":"Nhà sàn Trại Cá Hồi Séo Mý Tỷ","area":"Hồ Séo Mý Tỷ","lat":22.256,"lng":103.893,"type":"food","moods":["calm","energy"],"groups":["friends","couple","family","solo"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":75,"cost":350000,"desc":"Nhà sàn gỗ tại vùng nuôi cá nước lạnh lớn nhất Sa Pa với nguồn suối từ đỉnh Fansipan, phục vụ sashimi cá hồi thái lát dày, cá tầm nướng mắc khén và lẩu cá.","badges":["Ước tính ~350.000đ","250k–450k/người","Cá hồi & Cá tầm tại bè","Trong nhà"],"tip":"Cách đập chính Hồ Séo Mý Tỷ 500m–1 km. Nguồn protein tinh khiết và Omega-3 tươi sống cực tốt sau chặng đường cầm lái vượt 12 km đèo đá hộc.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM009', 28, '{"id":"AM009","name":"Nhà hàng 360° (Topas Ecolodge)","area":"Hồ Séo Mý Tỷ","lat":22.2686,"lng":103.9372,"type":"food","moods":["calm","nostalgia"],"groups":["couple","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":90,"cost":1100000,"desc":"Nhà hàng khung nhà sàn gỗ người Tày bao bọc bởi cửa kính 360 độ ngắm biển mây, phục vụ cá hồi Séo Mý Tỷ xông khói lạnh kiểu Đan Mạch, thăn bò áp chảo và ức vịt sốt cam.","badges":["Ước tính ~1.100.000đ","700k–1,5tr/người","Ẩm thực Bắc Âu view 360°","Trong nhà"],"tip":"Cách Hồ Séo Mý Tỷ ~14 km ngay trục đường chính từ Mường Hoa rẽ đi Séo Mý Tỷ. Nên đặt bàn trước để có vị trí ngồi cạnh vách kính nhìn ra thung lũng mây.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM010', 29, '{"id":"AM010","name":"Quán ăn Hợp tác xã & Chợ Bản Tả Phìn","area":"Bản Tả Phìn","lat":22.3931,"lng":103.8344,"type":"food","moods":["nostalgia","energy"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":45,"cost":110000,"desc":"Các quán cơm gia đình bình dân của người Dao Đỏ nấu bếp củi truyền thống với thịt lợn cắp nách gác bếp xào gừng tỏi, gà đồi chấm chẩm chéo, măng rừng xào bò.","badges":["Ước tính ~110.000đ","70k–150k/người","Cơm gia đình Dao Đỏ","Trong nhà"],"tip":"Nằm ngay ngã ba trung tâm Bản Tả Phìn (cách Tu Viện 800m, Hang Tả Phìn 1 km). Khẩu phần thịt rất đầy đặn, nạp đạm và tinh bột nhanh gọn, tiết kiệm.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM011', 30, '{"id":"AM011","name":"Nhà hàng Stone Garden (Vườn Đá Tả Phìn)","area":"Bản Tả Phìn","lat":22.3925,"lng":103.835,"type":"food","moods":["nostalgia","calm"],"groups":["couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":75,"cost":310000,"desc":"Nhà hàng gỗ thông và đá tự nhiên giữa bãi đá vôi rêu phong cổ kính, nổi tiếng với Mẹt lợn bản 5 món, gà đen hầm thuốc bắc nấm hương rừng và cá suối chiên giòn.","badges":["Ước tính ~310.000đ","220k–400k/người","Mẹt lợn bản 5 món","Trong nhà"],"tip":"Cách Tu Viện Tả Phìn ~1 km. Bối cảnh vườn đá rêu phong cực hợp chụp máy ảnh compact Y2K/mirrorless cổ điển; tiện ăn trưa ngay sau khi tắm lá thuốc Dao Đỏ.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM012', 31, '{"id":"AM012","name":"Nhà hàng Tả Phìn (KK Sapa Hotel)","area":"Bản Tả Phìn","lat":22.3315,"lng":103.8458,"type":"food","moods":["calm","energy"],"groups":["couple","family","friends","solo"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":75,"cost":875000,"desc":"Nhà hàng 5 sao sang trọng nhìn thẳng ra dãy Hoàng Liên Sơn, phục vụ À la carte và Buffet cao cấp với bít tết thăn ngoại bò Mỹ, sườn cừu nướng thảo mộc, ức gà sốt nấm.","badges":["Ước tính ~875.000đ","550k–1,2tr/người","Ẩm thực Á–Âu 5 sao","Trong nhà"],"tip":"Cách Bản Tả Phìn ~12 km. Quầy đồ ăn giàu đạm (bò Mỹ, ức gà, cừu) được phân khu rõ ràng, rất dễ kiểm soát dinh dưỡng cho người tập luyện thể hình.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM013', 32, '{"id":"AM013","name":"Cụm quán nướng Trạm Tôn (Cổng Thác Tình Yêu)","area":"Thác Tình Yêu","lat":22.3486,"lng":103.7764,"type":"food","moods":["energy","adventure"],"groups":["couple","friends","solo","family"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":35,"cost":85000,"desc":"Dãy quán nhỏ đỏ rực lửa than hồng ở độ cao gần 2.000m ngay cổng Thác Tình Yêu, chuyên thịt lợn bản xiên nướng mắc khén, bò cuốn cải mèo, chim cút quay, cơm lam.","badges":["Ước tính ~85.000đ","50k–120k/người","Nướng than hồng đỉnh đèo","Ngoài trời"],"tip":"Nằm ngay sát bãi gửi xe và cổng soát vé Thác Tình Yêu (0 km). Ngồi sưởi ấm ăn thịt xiên nướng nóng hổi ngay sau khi đi bộ 3 km khứ hồi từ thác ra cực kỳ hợp.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM014', 33, '{"id":"AM014","name":"Nhà hàng Ô Quy Hồ (Đỉnh đèo Ô Quy Hồ)","area":"Thác Tình Yêu","lat":22.355,"lng":103.762,"type":"food","moods":["adventure","calm","energy"],"groups":["friends","couple","family","solo"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":75,"cost":350000,"desc":"Nhà hàng không gian mở nằm chênh vênh trên đỉnh đèo Ô Quy Hồ nhìn thẳng xuống vực sâu và biển mây, chuyên lẩu cá tầm măng chua, lẩu gà đen ớt hiểm, bò tơ hấp.","badges":["Ước tính ~350.000đ","250k–450k/người","Lẩu đỉnh đèo & Săn mây","Trong nhà"],"tip":"Cách cổng Thác Tình Yêu 2,5–3 km về phía Lai Châu. Có khu vực sưởi ấm và bãi đỗ xe cực rộng ngay mặt đường Quốc lộ 4D.","priceQuality":"est"}', 1793156335025);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM015', 34, '{"id":"AM015","name":"Nhà hàng Hillside (Lady Hill Sapa Resort)","area":"Thác Tình Yêu","lat":22.3415,"lng":103.8365,"type":"food","moods":["calm","nostalgia"],"groups":["couple","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":90,"cost":1000000,"desc":"Nhà hàng kiến trúc vòm kính sang trọng nhìn thẳng ra đỉnh Fansipan giữa đồi thông 22 ha, phục vụ ẩm thực Fine Dining hữu cơ: thăn bò Úc nướng đá nóng, cá tầm đút lò.","badges":["Ước tính ~1.000.000đ","600k–1,4tr/người","Fine Dining Hữu cơ","Trong nhà"],"tip":"Cách cổng Thác Tình Yêu 11,5–12 km. Không gian cực kỳ riêng tư, lãng mạn, rất thích hợp cho các cặp đôi hẹn hò sau chuyến đi Thác Tình Yêu.","priceQuality":"est"}', 1793156335025);
